const crypto = require('crypto');

// Verifies the HMAC-SHA256 signature the Go backend stamps into X-Signature
// (internal/observability/notifier.go, internal/notification/dispatcher/admin.go)
// before any downstream node acts on the payload. Without this check, anyone
// who can reach this webhook path (e.g. from a compromised sibling container
// on the internal network) could forge KYC/payout events and trigger phishing
// emails or fraudulent manual-transfer instructions to operators.
const item = $input.first();
const headers = (item.json && item.json.headers) || {};
const sigHeader = String(headers['x-signature'] || '').trim();
const secret = process.env.N8N_WEBHOOK_SECRET || '';

if (!secret) {
  throw new Error('N8N_WEBHOOK_SECRET is not configured on this n8n instance \u2014 refusing to process an unverifiable webhook call');
}

const rawBase64 = item.binary && item.binary.data && item.binary.data.data;
if (!rawBase64) {
  throw new Error('Raw request body not available \u2014 the Webhook Trigger node must have "Raw Body" enabled');
}
const rawBuffer = Buffer.from(rawBase64, 'base64');

const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(rawBuffer).digest('hex');
const expectedBuf = Buffer.from(expected);
const gotBuf = Buffer.from(sigHeader);
const valid = expectedBuf.length === gotBuf.length && crypto.timingSafeEqual(expectedBuf, gotBuf);

if (!valid) {
  throw new Error('Invalid or missing X-Signature header \u2014 request rejected before any notification action was taken');
}

let parsedBody = {};
if (rawBuffer.length) {
  try {
    parsedBody = JSON.parse(rawBuffer.toString('utf8'));
  } catch (e) {
    throw new Error('Signed body is not valid JSON: ' + e.message);
  }
}

// Reconstruct the same { headers, params, query, body } shape n8n produces
// without Raw Body enabled, so every downstream node's existing
// `$input.first().json.body ?? $input.first().json` access keeps working
// unchanged.
return [{ json: { headers, params: item.json.params || {}, query: item.json.query || {}, body: parsedBody } }];

const p = ($input.first().json.body ?? $input.first().json);
const amountGTQ = (p.frozen_amount_cents / 100).toFixed(2);
return [{
  json: {
    subject: `[COMPLIANCE] KYC balance frozen — Q${amountGTQ} GTQ (User ${p.user_id})`,
    emailBody: `A user's balance has been automatically frozen pending KYC verification.

User ID: ${p.user_id}
Frozen amount: Q${amountGTQ} GTQ
Reason: ${p.reason}
Trace ID: ${p.trace_id}

Action required: Review the user's KYC submission and release the freeze after approval.
Admin panel: ${'https://kiniela.uk'}/admin/kyc/frozen-balances`
  }
}];
